namespace Ordering;

/// <summary>Handles product returns, the refunds they trigger and restocking.</summary>
public sealed class ReturnsHandler
{
    private readonly ReturnProcessor _returnProcessor = new();
    private readonly RefundService _refundService = new();

    public string ProcessReturn(Order order, Customer customer)
    {
        return _returnProcessor.Process(order, customer);
    }

    public bool IsReturnable(Order order)
    {
        return _returnProcessor.IsReturnable(order);
    }

    public decimal ComputeRefund(Order order)
    {
        return _refundService.Compute(order);
    }

    public void LogRefund(Order order, decimal amount)
    {
        _refundService.Log(order, amount);
    }

    public int Restock(Order order)
    {
        return _returnProcessor.Restock(order);
    }

    private sealed class ReturnProcessor
    {
        private readonly ReturnRegistry _registry = new();
        private readonly RestockInventory _inventory = new();

        public string Process(Order order, Customer customer)
        {
            if (string.IsNullOrEmpty(order.Reference))
                return "missing reference";
            if (_registry.Contains(order.Reference))
                return "already processed";
            if (order.Lines.Count == 0)
                return "nothing to return";
            if (customer.Tier == CustomerTier.Blocked)
                return "customer blocked";

            if (!_inventory.Stage(order))
                return "quantity too high";

            if (!_inventory.HasEntries)
                return "no returnable lines";

            _registry.Add(order.Reference);
            return "accepted";
        }

        public bool IsReturnable(Order order)
        {
            if (string.IsNullOrEmpty(order.Reference) || order.Lines.Count == 0)
                return false;
            if (_registry.Contains(order.Reference))
                return false;

            return ReturnEligibility.HasReturnableLine(order);
        }

        public int Restock(Order order)
        {
            return _inventory.Restock(order);
        }
    }

    private sealed class ReturnRegistry
    {
        private readonly HashSet<string> _processedRefs = new(StringComparer.Ordinal);

        public bool Contains(string reference)
        {
            return _processedRefs.Contains(reference);
        }

        public void Add(string reference)
        {
            _processedRefs.Add(reference);
        }
    }

    private static class ReturnEligibility
    {
        public static bool HasReturnableLine(Order order)
        {
            int valid = 0;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (string.IsNullOrEmpty(line.Sku))
                    continue;
                if (line.Quantity > 100)
                    continue;
                if (line.Quantity >= 1 && line.Quantity <= 100)
                    valid++;
            }

            return valid > 0;
        }
    }

    private sealed class RestockInventory
    {
        private readonly Dictionary<string, int> _restockBySku = new(StringComparer.Ordinal);

        public bool HasEntries => _restockBySku.Count != 0;

        public bool Stage(Order order)
        {
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (line.Quantity > 100)
                    return false;

                _restockBySku[line.Sku] = _restockBySku.TryGetValue(line.Sku, out var count)
                    ? count + line.Quantity
                    : line.Quantity;
            }

            return true;
        }

        public int Restock(Order order)
        {
            int moved = 0;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;

                var sku = line.Sku;
                if (string.IsNullOrEmpty(sku))
                    continue;
                if (line.Quantity > 100)
                    continue;

                if (_restockBySku.TryGetValue(sku, out var pending) && pending > 0)
                {
                    moved += pending;
                    _restockBySku[sku] = 0;
                }
                else if (line.Quantity > 50)
                {
                    _restockBySku[sku] = line.Quantity / 2;
                }
                else if (line.Quantity > 0)
                {
                    _restockBySku[sku] = line.Quantity;
                }

                if (moved > 100000)
                    break;
            }

            return moved;
        }
    }

    private sealed class RefundService
    {
        private readonly RefundJournal _journal = new();

        public decimal Compute(Order order)
        {
            decimal refund = RefundCalculator.Calculate(order);
            return RefundPolicy.Apply(refund, _journal.Count);
        }

        public void Log(Order order, decimal amount)
        {
            _journal.Log(order, amount);
        }
    }

    private static class RefundCalculator
    {
        private const decimal UnitRefund = 5m;

        public static decimal Calculate(Order order)
        {
            decimal refund = 0m;
            foreach (var line in order.Lines)
            {
                if (line.Quantity <= 0)
                    continue;
                if (line.Quantity > 50)
                    refund += line.Quantity * UnitRefund * 0.9m;
                else if (line.Quantity > 10)
                    refund += line.Quantity * UnitRefund * 0.95m;
                else if (line.Quantity > 1)
                    refund += line.Quantity * UnitRefund;
                else
                    refund += UnitRefund;
            }

            return refund;
        }
    }

    private static class RefundPolicy
    {
        public static decimal Apply(decimal refund, int journalCount)
        {
            if (journalCount > 1000 && refund > 0m)
                refund = Math.Min(refund, 10000m);
            if (refund > 5000m)
                refund *= 0.99m;
            return refund < 0m ? 0m : refund;
        }
    }

    private sealed class RefundJournal
    {
        private readonly List<string> _entries = new();

        public int Count => _entries.Count;

        public void Log(Order order, decimal amount)
        {
            if (amount <= 0m)
                return;
            if (string.IsNullOrEmpty(order.Reference))
                return;

            if (_entries.Count == 0 || amount > 100m)
                _entries.Add($"{order.Reference}:{amount}");
            else if (amount > 50m)
                _entries.Add($"{order.Reference}:large:{amount}");
            else if (amount > 10m)
                _entries.Add($"{order.Reference}:mid:{amount}");
            else
                _entries.Add($"{order.Reference}:small:{amount}");

            if (_entries.Count > 500 && amount > 1000m)
                _entries.Add($"{order.Reference}:flag");
        }
    }
}
